"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[9138],{89138:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/the-traffic-officers-night.png\\"\\n          title=\\"교통경찰의 밤\\"\\n          author=\\"히가시노 게이고\\"\\n          publisher=\\"바움\\"\\n          publishedDate=\\"2010-01-15\\"\\n          isbn=\\"9788958830764\\"\\n          rating=3.5\\n          tags=\\"thriller\\"\\n        />\\n</center>\\n\\n## Review\\n이 작품은 교통법규 위반이라는 지극히 일상적인 소재를 현미경 삼아 인간의 이기심, 책임감, 그리고 법적 정의와 도덕적 정의 사이의 메울 수 없는 간극을 나타낸다.  \\n<br>\\n이 작품은 여섯 편의 단편으로 이루어져 있으며 ```사소한 교통법규 위반```이 돌이킬 수 없는 비극으로 증폭되는 과정을 보여준다.  \\n<br>\\n특히 첫 번째 작품인 <mark>천사의 귀</mark>는 사회적 선입견에 의해 사건이 왜곡됨을 보여준다.  \\n<br>\\n```누구나 다 하는 건데```라는 자기 합리화가 모든 비극의 심리적 근원이다.  \\n우리 모두를 위한 경고등 역할을 하는 작품이다."}')}}]);